import java.io.*;
import java.util.*;

public class Main {
    static final PrintWriter output = new PrintWriter(System.out);
    static final FastReader inputReader = new FastReader();

    public static void main(String[] args) {
        int testCasesCount = 1;
        for (int i = 0; i < testCasesCount; i++) {
            processInput();
        }
        output.flush();
    }

    public static void processInput() {
        int totalPoints = readInt();
        double thresholdProbability = readDouble();

        int lowIndex = 0;
        int highIndex = totalPoints - 1;
        while (lowIndex < highIndex) {
            int midIndex = (lowIndex + highIndex) / 2;
            double currentProb = computeProbability(midIndex, totalPoints);
            if (currentProb >= thresholdProbability) {
                highIndex = midIndex;
            } else {
                lowIndex = midIndex + 1;
            }
        }
        output.println(lowIndex);
    }

    private static double computeProbability(int m, int n) {
        long totalComb = choose(n, 3);
        double probSum = 0.0;
        probSum += (double) choose(m, 3);
        probSum += (double) (choose(m, 2) * choose(n - m, 1));
        probSum += 0.5 * (choose(m, 1) * choose(n - m, 2));
        return probSum / totalComb;
    }

    private static long choose(int n, int c) {
        if (c > n) return 0;
        if (c == n) return 1;
        long res = 1;
        for (int i = 0; i < c; i++) {
            res *= (n - i);
        }
        for (int i = 1; i <= c; i++) {
            res /= i;
        }
        return res;
    }

    static int readInt() {
        return inputReader.nextInt();
    }

    static double readDouble() {
        return inputReader.nextDouble();
    }
}
